impl Solution {
    pub fn stone_game_v(stone_value: Vec<i32>) -> i32 {
        let n = stone_value.len();
        let mut dp = vec![vec![0; n]; n];

        for i in (0..n).rev() {
            for j in i + 1..n {
                let mut max_score = 0;
                for k in i..j {
                    let left_sum: i32 = stone_value[i..=k].iter().sum();
                    let right_sum: i32 = stone_value[k + 1..=j].iter().sum();
                    let score = if left_sum < right_sum {
                        left_sum + dp[i][k]
                    } else if left_sum > right_sum {
                        right_sum + dp[k + 1][j]
                    } else {
                        std::cmp::max(left_sum + dp[i][k], right_sum + dp[k + 1][j])
                    };
                    max_score = std::cmp::max(max_score, score);
                }
                dp[i][j] = max_score;
            }
        }

        dp[0][n - 1]
    }
}

